// DEV_RIO_103 Content + QA + Approval — dry-run
// 実運用ではAI生成を上流に置く。dry-runでは入力をそのまま検査。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-note-001',
  media: i.media ?? 'note',
  note_body: i.note_body ?? '（本文サンプル）AIで店舗の雑務を減らす手順…',
  threads_post: i.threads_post ?? '雑務、AIに投げてます。手順はnoteに。',
  cta: i.cta ?? 'Brainで7日分のテンプレを配布中',
  affiliate: i.affiliate ?? null,
  ad_disclosure: i.ad_disclosure ?? (i.affiliate ? 'PR' : null)
} }];

// QA: PR表記・アフィリ規約・空本文などの最低限チェック → PASS/FIX_REQUIRED/BLOCK
// 本格判定は quality-reviewer / sns-post-quality-check に委譲（design/RISK_APPROVAL_POLICY.md）。
const o = $input.first().json;
const issues = [];
if (o.affiliate && !o.ad_disclosure) issues.push('アフィリ掲載だがPR表記なし');
if (!o.note_body || o.note_body.length < 20) issues.push('本文が短すぎ/空');
if (!o.cta) issues.push('CTAなし');
let qa_status;
if (o.affiliate && !o.ad_disclosure) qa_status = 'BLOCK';
else if (issues.length) qa_status = 'FIX_REQUIRED';
else qa_status = 'PASS';
const state = qa_status === 'PASS' ? 'WAITING_APPROVAL' : (qa_status === 'BLOCK' ? 'DEAD_LETTER_QUEUE' : 'FAILED_RETRYABLE');
return [{ json: { ...o, qa_status, issues, state, owner_yes_no: 'PENDING',
  note: 'dry-run。PASS→人間承認待ち(WAITING_APPROVAL)。公開はしない。' } }];
